<?php namespace App\Repositories\MySQL; use App\Database\MySQLConnection; use App\Repositories\Interfaces\ContactRepositoryInterface;
final class MySQLContactRepository implements ContactRepositoryInterface { public function __construct(private MySQLConnection $db){} public function all():array{return $this->db->pdo()->query('SELECT * FROM contacts ORDER BY created_at DESC')->fetchAll();} public function find(string $id):?array{$s=$this->db->pdo()->prepare('SELECT * FROM contacts WHERE id=?');$s->execute([$id]);return $s->fetch()?:null;} public function save(array $d):string{$s=$this->db->pdo()->prepare('INSERT INTO contacts(name,email,subject,message) VALUES(?,?,?,?)');$s->execute([$d['name'],$d['email'],$d['subject'],$d['message']]);return (string)$this->db->pdo()->lastInsertId();} public function delete(string $id):bool{$s=$this->db->pdo()->prepare('DELETE FROM contacts WHERE id=?');return $s->execute([$id]);} public function count():int{return (int)$this->db->pdo()->query('SELECT COUNT(*) FROM contacts')->fetchColumn();} }
